def build_tree(F, y, depth, minleaf=5):
    # returns (pred, feat, thr, left, right)
    if depth==0 or len(set(y))==1 or len(y)<2*minleaf:
        return ('leaf', np.bincount(y,minlength=4).argmax(), (y==np.bincount(y,minlength=4).argmax()).sum())
    best=None
    n=len(y)
    tot = np.bincount(y,minlength=4)
    for f in range(F.shape[1]):
        vals=np.unique(F[:,f])
        for t in vals[:-1]:
            l = F[:,f]<=t; r=~l
            if l.sum()<minleaf or r.sum()<minleaf: continue
            cl=np.bincount(y[l],minlength=4); cr=np.bincount(y[r],minlength=4)
            score = cl.max()+cr.max()
            if best is None or score>best[0]:
                best=(score,f,t,l,r)
    if best is None:
        p=np.bincount(y,minlength=4).argmax(); return ('leaf',p,(y==p).sum())
    _,f,t,l,r=best
    return ('node',f,t,build_tree(F[l],y[l],depth-1,minleaf),build_tree(F[r],y[r],depth-1,minleaf))
